input.content:
import { cookies, headers } from 'next/headers'

function getPreferredLanguage(acceptLanguage: string | null) {
  if (!acceptLanguage) return 'unknown'
  return acceptLanguage.split(',')[0].split(';')[0].trim()
}

export default async function UserPreferences() {
  const cookieStore = await cookies()
  const headersList = await headers()

  const theme = cookieStore.get('theme')?.value ?? 'light'
  const language = getPreferredLanguage(headersList.get('accept-language'))

  return (
    <section>
      <p>Theme: {theme}</p>
      <p>Preferred language: {language}</p>
    </section>
  )
}

